export function ChildComponent({
  parentLabel = "{{parentLabel}}",
  childLabel = "{{childLabel}}",
  grandchild = {{grandchild}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "12px system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 10, width: 280, boxSizing: "border-box", border: `2px dashed ${accent}`, position: "relative" }}>
      <span style={{ position: "absolute", top: -9, left: 10, background: "#FAF7F2", padding: "0 6px", fontWeight: 700 }}>{parentLabel}</span>
      <div style={{ marginTop: 12, border: `2px solid ${accent}`, borderRadius: 8, padding: "20px 14px 14px", position: "relative", minHeight: 40 }}>
        <span style={{ position: "absolute", top: -9, left: 10, background: accent, color: "#241430", borderRadius: 4, padding: "0 6px" }}>{childLabel}</span>
        {grandchild && (
          <div style={{ marginTop: 10, border: "2px dotted #24143060", background: "#24143008", borderRadius: 8, padding: "20px 14px 14px", position: "relative" }}>
            <span style={{ position: "absolute", top: -9, left: 10, background: "#FAF7F2", color: "#24143099", padding: "0 6px" }}>Label</span>
          </div>
        )}
      </div>
    </div>
  );
}
